package com.captainslog;

import net.runelite.client.config.*;

import java.awt.*;

@ConfigGroup("CaptainsLog")
public interface CaptainsLogConfig extends Config
{

    @ConfigSection(
            name = "Overlay",
            description = "Configuration settings related to Overlay",
            position = 0
    )
    String overlaySection = "Overlay";

    @ConfigItem(
            keyName = "showOverlay",
            name = "Show Overlay",
            description = "Show the on-screen crew list",
            position = 0,
            section = overlaySection
    )
    default boolean showOverlay()
    {
        return true;
    }


    @ConfigItem(
            keyName = "removeOverlayTicks",
            name = "Remove Overlay Ticks",
            description = "Number of ticks before the player is off the boat before overlay disappears (default 5 min)",
            position = 4,
            section = overlaySection
    )
    default int removeOverlayTicks()
    {
        return 500;
    }
    @ConfigItem(
            keyName = "removeCrewmateTicks",
            name = "Remove Crewmate Ticks",
            description = "Number of ticks before crewmate is removed from crewlist (default 5 min)",
            position = 5,
            section = overlaySection
    )
    default int removeCrewmateTicks()
    {
        return 500;
    }

    @ConfigItem(
            keyName = "showCount",
            name = "Show player count",
            description = "Show the number of crewmates in the overlay header",
            position = 1,
            section = overlaySection
    )
    default boolean showCount()
    {
        return true;
    }

    @ConfigItem(
            keyName = "showTime",
            name = "Show player time",
            description = "Show the time a crewmate is on the ship",
            position = 2,
            section = overlaySection
    )
    default boolean showTime()
    {
        return true;
    }

    @ConfigItem(
            keyName = "sortAlphabetically",
            name = "Sort alphabetically",
            description = "Sort player names alphabetically in the overlay",
            position = 3,
            section = overlaySection
    )
    default boolean sortAlphabetically()
    {
        return false;
    }

    @ConfigSection(
            name = "UI",
            description = "Configuration settings related to UI",
            position = 1
    )
    String UISection = "UI";

    @Alpha
    @ConfigItem(
            keyName = "onboardColor",
            name = "Onboard color",
            description = "Color for onboard crewmmates",
            position = 0,
            section = UISection
    )
    default Color onboardColor()
    {
        return Color.GREEN;
    }

    @Alpha
    @ConfigItem(
            keyName = "offboardColor",
            name = "Offboard color",
            description = "Color for crewmmates no longer onboard",
            position = 1,
            section = UISection
    )
    default Color offboardColor()
    {
        return Color.YELLOW;
    }

    @ConfigSection(
            name = "Debug",
            description = "Debug Section",
            position = 2
    )
    String debugSection = "Debug";

    @ConfigItem(
            keyName = "debug",
            name = "Show debug info",
            description = "Show debug info",
            position = 0,
            section = debugSection
    )
    default boolean showDebugInfo()
    {
        return false;
    }

}

package com.captainslog;

import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;

import static com.captainslog.CaptainsLogPlugin.formatDurationTicks;

@Singleton
public class CaptainsLogPanelOverlay extends OverlayPanel
{
    private final CaptainsLogPlugin plugin;
    private final CaptainsLogConfig config;

    private static final int SKIFF_WORLDVIEW_ID = 2;
    private static final int SLOOP_WORLDVIEW_ID = 3;

    @Inject
    private CaptainsLogPanelOverlay(CaptainsLogPlugin plugin, CaptainsLogConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        // ✅ allow Alt-drag & snapping
        setMovable(true);
        setSnappable(true);
        setDragTargetable(true);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        List<String> onboardCrew = plugin.getCrewList();
        Map<String, Integer> ticksOnboard = plugin.getTicksOnShip();
        List<Map.Entry<String, Integer>> allList = new ArrayList<>(ticksOnboard.entrySet());

        if (config.sortAlphabetically())
        {
            allList.sort(Map.Entry.comparingByKey(String.CASE_INSENSITIVE_ORDER));
        } else {
            allList.sort(Map.Entry.<String, Integer>comparingByValue().reversed());
        }

        // Title
        String title = "Crew List";
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text(title)
                        .color(Color.WHITE)
                        .build()
        );

        if (!plugin.isOnBoat()) {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Paused:")
                            .right("Return to ship")
                            .leftColor(Color.WHITE)
                            .rightColor(Color.CYAN)
                            .build()
            );
        }

        // Capacity
        int total;
        switch (plugin.getBoatType()) {
            case 1: // raft
                total = 2;
                break;
            case 2: // Skiff
                total = 5;
                break;
            case 3: // Sloop
                total = 10;
                break;
            default:
                total = -1;
        }
        if (config.showCount() && total != -1)
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("Crew Capacity:")
                            .right(Integer.toString(onboardCrew.size()) + "/" + total)
                            .leftColor(Color.LIGHT_GRAY)
                            .rightColor(Color.CYAN)
                            .build()
            );
        }

        if (allList.isEmpty())
        {
            panelComponent.getChildren().add(
                    LineComponent.builder()
                            .left("No crew")
                            .leftColor(Color.GRAY)
                            .build()
            );
        }
        else
        {
            for (Map.Entry entry : allList)
            {
                String name = entry.getKey().toString();
                String time = "";
                if (config.showTime()) {
                    Integer ticks = (Integer) entry.getValue();
                    time = formatDurationTicks(ticks);
                }
                Color textColor;
                if (onboardCrew.contains(name)) {
                    textColor = config.onboardColor();
                } else {
                    textColor = config.offboardColor();
                }
                panelComponent.getChildren().add(
                        LineComponent.builder()
                                .left(name)
                                .right(time)
                                .leftColor(textColor)
                                .rightColor(Color.WHITE)
                                .build()
                );
            }
        }

        return super.render(graphics);
    }
}

package com.captainslog;

import javax.inject.Inject;

import com.google.inject.Provides;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.*;
import net.runelite.api.gameval.VarbitID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.party.PartyService;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;

import java.util.*;

@Slf4j
@PluginDescriptor(
	name = "Captain's Log",
	description = "Track other players on your boat, etc.",
	tags = {"sailing", "deep", "sea", "trawling", "captains", "log", "crew"}
)

public class CaptainsLogPlugin extends Plugin
{

	private static final String CONFIG_GROUP_KEY = "CaptainsLog";
	@Inject
	private Client client;

	@Inject
	private CaptainsLogConfig config;
	@Inject
	private CaptainsLogPanelOverlay overlay;
	@Inject
	private DebugPanelOverlay debug;
	@Inject
	private ClientThread clientThread;
	@Inject
	private ConfigManager configManager;

	@Inject
	private PartyService partyService;
	@Inject
	private OverlayManager overlayManager;

	@Getter
	private boolean isOnBoat = false;
	@Getter
	private int ticksOffBoat = Integer.MAX_VALUE; // number of ticks player has been off boat

	@Getter
	private List<String> crewList = Collections.emptyList();
	@Getter
	private Map<String, Integer> ticksOnShip = new HashMap<>();
	@Getter
	private Map<String, Integer> ticksOffShip = new HashMap<>();
	public final int RAFT_WORLD_ENTITY_TYPE = 1;
	public final int SKIFF_WORLD_ENTITY_TYPE = 2;
	public final int SLOOP_WORLD_ENTITY_TYPE = 3;
	public Map<Integer, Integer> boats = new HashMap<>();

	@Provides
	CaptainsLogConfig provideConfig(ConfigManager cm)
	{
		return cm.getConfig(CaptainsLogConfig.class);
	}

	@Override
	protected void startUp() throws Exception
	{
		if (shouldShowOverlay())
		{
			overlayManager.add(overlay);
		}

		if (config.showDebugInfo()) {
			overlayManager.add(debug);
		}
	}

	@Override
	protected void shutDown() throws Exception
	{
		overlayManager.remove(overlay);
		overlayManager.remove(debug);
	}

	@Subscribe
	public void onConfigChanged(ConfigChanged event)
	{
		if (!event.getGroup().equals(CONFIG_GROUP_KEY))
		{
			return;
		}

		if ("showOverlay".equals(event.getKey()))
		{
			if (shouldShowOverlay())
			{
				overlayManager.add(overlay);
			}
			else
			{
				overlayManager.remove(overlay);
			}
		}

		if ("debug".equals(event.getKey()))
		{
			if (config.showDebugInfo())
			{
				overlayManager.add(debug);
			}
			else
			{
				overlayManager.remove(debug);
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick tick)
	{
		if (client.getGameState() != GameState.LOGGED_IN)
		{
			return;
		}

		final Player local = client.getLocalPlayer();
		if (local == null)
		{
			crewList = Collections.emptyList();
			return;
		}

		final WorldView rootView = client.getTopLevelWorldView();
		if (rootView == null)
		{
			crewList = Collections.emptyList();
			return;
		}

		if (shouldShowOverlay())
		{
			overlayManager.add(overlay);
		}
		else
		{
			overlayManager.remove(overlay);
		}

		if (!isOnBoat) {
			// prevent overflow
			if (ticksOffBoat < Integer.MAX_VALUE) {
				ticksOffBoat += 1;
			}
		} else {
			ticksOffBoat = 0;
		}

		List<Player> foundCrew = new ArrayList<>();
		// only update crew list when on boat
		if (isOnBoat) {
			findCrew(local.getWorldView(), foundCrew);
			List<String> crewNames = new ArrayList<>();

			for (Player p : foundCrew) {
				if (p == null)
				{
					continue;
				}
				String name = p.getName();
				if (name != null && !name.isEmpty())
				{
					crewNames.add(name);
				}
			}

			for (String name : crewNames)
			{
				ticksOnShip.merge(name, 1, Integer::sum);
			}

			crewList = Collections.unmodifiableList(crewNames);

			for (String crewname : ticksOnShip.keySet()) {
				if (crewList.contains(crewname)) {
					// crew is on board, reset to 0
					ticksOffShip.put(crewname, 0);
				} else {
					ticksOffShip.merge(crewname, 1, Integer::sum);
					// crew is off for x ticks, remove them
					if (ticksOffShip.get(crewname) > config.removeCrewmateTicks()) {
						ticksOnShip.remove(crewname);
					}
				}
			}
		}

		if (!shouldKeepInfo()) {
			if (!ticksOnShip.isEmpty()) {
				ticksOnShip = new HashMap<>();
			}
			if (!ticksOffShip.isEmpty()) {
				ticksOffShip = new HashMap<>();
			}
		}
	}

	static String formatDurationTicks(int ticks)
	{
		long totalMillis = ticks * 600L;
		long totalSeconds = totalMillis / 1000L;
		long totalMinutes = totalSeconds / 60L;
		long minutes = totalMinutes % 60L;
		long hours = totalSeconds / 3600L;
		long seconds = totalSeconds % 60L;
		if (hours == 0) {
			return String.format("%02d:%02d", minutes, seconds);
		} else {
			return String.format("%d:%02d:%02d", hours, minutes, seconds);
		}
	}

	@Subscribe
	public void onVarbitChanged(VarbitChanged e) {
		int changed = e.getVarbitId();

		switch (changed) {
			case VarbitID.SAILING_PLAYER_IS_ON_PLAYER_BOAT:
				isOnBoat = e.getValue() == 1;
		}
	}

	@Subscribe
	public void onWorldEntitySpawned(WorldEntitySpawned event) {
		WorldEntity entity = event.getWorldEntity();
		WorldEntityConfig cfg = entity.getConfig();

		if (cfg == null) {
			return;
		}

		WorldView view = entity.getWorldView();
		if (view == null) return;
		if (cfg.getId() == RAFT_WORLD_ENTITY_TYPE || cfg.getId() == SKIFF_WORLD_ENTITY_TYPE || cfg.getId() == SLOOP_WORLD_ENTITY_TYPE) {
			boats.put(view.getId(), cfg.getId());
		}
	}
	public void onWorldEntityDespawned(WorldEntityDespawned event)
	{
		WorldEntity entity = event.getWorldEntity();
		WorldEntityConfig cfg = entity.getConfig();

		if (cfg == null) {
			return;
		}

		int worldViewId = entity.getWorldView().getId();

		boats.remove(worldViewId);
	}

	boolean shouldShowOverlay() {
		// shows overlay when
		// 		overlay enabled
		// 		user is on boat or shouldKeepInfo
		return config.showOverlay() && (isOnBoat || shouldKeepInfo());
	}

	boolean shouldKeepInfo() {
		// user left boat within the past x ticks (default 5 min, based on config)
		return ticksOffBoat <= config.removeOverlayTicks();
	}

	private void findCrew(WorldView worldView, List<Player> out)
	{
		for (Player p : worldView.players())
		{
			if (p != null)
			{
				out.add(p);
			}
		}
	}

	Integer getBoatType() {
		final Player localPlayer = client.getLocalPlayer();

		if (localPlayer == null || localPlayer.getWorldView() == null) return -1;
        return boats.getOrDefault(localPlayer.getWorldView().getId(), -1);
	}
}

package com.captainslog;

import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import javax.inject.Singleton;
import java.awt.*;
import java.util.List;
import java.util.Map;

@Singleton
public class DebugPanelOverlay extends OverlayPanel
{
    private final CaptainsLogPlugin plugin;
    private final CaptainsLogConfig config;

    @Inject
    private DebugPanelOverlay(CaptainsLogPlugin plugin, CaptainsLogConfig config)
    {
        this.plugin = plugin;
        this.config = config;

        setPosition(OverlayPosition.TOP_LEFT);
        setLayer(OverlayLayer.ABOVE_WIDGETS);

        // ✅ allow Alt-drag & snapping
        setMovable(true);
        setSnappable(true);
        setDragTargetable(true);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        panelComponent.getChildren().clear();

        List<String> names = plugin.getCrewList();
        Map<String, Integer> ticksOnboard = plugin.getTicksOnShip();

        // Title
        String title = "Debug";
        panelComponent.getChildren().add(
                TitleComponent.builder()
                        .text(title)
                        .color(Color.WHITE)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Is on boat:")
                        .right(String.valueOf(plugin.isOnBoat()))
                        .leftColor(Color.LIGHT_GRAY)
                        .rightColor(Color.CYAN)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Ticks off boat:")
                        .right(String.valueOf(plugin.getTicksOffBoat()))
                        .leftColor(Color.LIGHT_GRAY)
                        .rightColor(Color.CYAN)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("Overlay Ticks:")
                        .right(String.valueOf(config.removeOverlayTicks()))
                        .leftColor(Color.LIGHT_GRAY)
                        .rightColor(Color.CYAN)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("show overlay? ")
                        .right(String.valueOf(plugin.shouldShowOverlay()))
                        .leftColor(Color.LIGHT_GRAY)
                        .rightColor(Color.CYAN)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("keep overlay? ")
                        .right(String.valueOf(plugin.shouldKeepInfo()))
                        .leftColor(Color.LIGHT_GRAY)
                        .rightColor(Color.CYAN)
                        .build()
        );

        panelComponent.getChildren().add(
                LineComponent.builder()
                        .left("ship type: ")
                        .right(plugin.getBoatType().toString())
                        .leftColor(Color.LIGHT_GRAY)
                        .rightColor(Color.CYAN)
                        .build()
        );

        return super.render(graphics);
    }
}

